pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { 
        vm.deal(address(this), 3 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}(); 
    }
    function testRegression_property() public {
        bytes32 hash = keccak256(abi.encodePacked(blockhash(block.number)));
        vm.roll(block.number + 10);
        bytes32 futureHash = keccak256(abi.encodePacked(blockhash(block.number + 1)));
        vm.roll(block.number + 100);
        bytes32 targetHash = blockhash(block.number);
        vm.roll(block.number - 99);
        vm.prank(address(0x1));
        vm.deal(address(0x1), 1 ether);
        c.lockInGuess{value: 1 ether}(targetHash);
        vm.roll(block.number + 2);
        vm.prank(address(0x1));
        c.settle();
        vm.prank(address(0x1));
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }
        assertTrue(!ok, "Second settle should revert in reference");
    }
}
